window.RP_SESSION={"id":"S-92704a0f9441","messages":[{"id":"RP-III-0165574","time":"2026-09-05T02:40:00+09:00","room":"RP III","name":"인물 미확정 — 아버지에게 편지를 쓰는 인물","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":" 아버지에게.\n\n여동생을 만났습니다. 그러지 않기를 바라셨겠습니다만, 적어도 두 사람의 뜻은 그렇지 않았던 탓인지도 모릅니다.\n\n얼굴에는 당신이 손에 쥐어준 적도 없는, 개 가면을 쓰고 있더랍니다. 하여 저는 낮이 되기 전까지 그 뒤의 눈을 마주칠수도 없었습니다.\n\n불씨 위에서나 볼 수 있었던 눈은 여전히 검기도 검었습니다. 그런데도 그 총기, 어머니는 알고 아버지는 모르시던 총기는 죽고 없었습니다. 5년도 더 지나서 다시 만난 눈 너머를 내다보려 애썼습니다. 한숨이라도 턱턱 내쉬지 않고서야 견딜 일도 못 됐습니다.\n\n그는 고운 살에 붉은 줄이 한 줄 두 줄 그어지고, 그리고 또 옷이 다 헤져가면서까지 가시박과 찔레꽃을 헤쳐가야 했겠죠. 아버지는 그가 살고자 한다면 몇 그루의 나무를 지나야 할지 짐작이나 할 줄 아는 사람이셨습니까? \n\n오로지 홀로 자랐다고 생각하는 이는 어른이 될 수도 없다고 누군가 그러더랍니다. 그런데 저는 이제서야 번듯한 삶으로 부딪히는데도 그 전환점 가운데 아","characters":[]},{"id":"RP-III-0165575","time":"2026-09-05T02:40:00+09:00","room":"RP III","name":"인물 미확정 — 아버지에게 편지를 쓰는 인물","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0165576","time":"2026-09-05T02:41:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-III-0165577","time":"2026-09-05T03:06:00+09:00","room":"RP III","name":"션","profile":"션","identity":"unresolved","type":"dialogue","body":"!모닥불","characters":[]},{"id":"RP-III-0165578","time":"2026-09-05T03:06:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]}]};
